                      "4. Как пройдёт прогулка: где, сколько, на поводке или без?\n"
                      "5. Будете ли гулять с другими собаками одновременно?\n"
                      "6. Как вы сообщаете, что прогулка прошла?\n\n"
                      "### О сложных ситуациях\n\n"
